exp = {0:0x2144DF1C, 1:0xA505DF1B, 0x12345678:0x4A090E98, 0xFFFFFFFF:0xFFFFFFFF, 42:0xE6599437}
def bits_le_of_bytes(data):
    o=[]
    for byte in data:
        for i in range(8): o.append((byte>>i)&1)
    return o
def bits_be_of_bytes(data):
    o=[]
    for byte in data:
        for i in range(8): o.append((byte>>(7-i))&1)
    return o
def bits_int_lsb(V): return [(V>>i)&1 for i in range(32)]
def bits_int_msb(V): return [(V>>(31-i))&1 for i in range(32)]
orders = {
 "int_lsb": bits_int_lsb,
 "int_msb": bits_int_msb,
}
# byte-based orders need per-V bytes
def crc_ref(bits, init, xorout):
    c=init
    for b in bits:
        fb=(c&1)^b
        c>>=1
        if fb: c^=0xEDB88320
    return (c^xorout)&0xFFFFFFFF
def crc_noref(bits, init, xorout):
    c=init
    for b in bits:
        fb=((c>>31)&1)^b
        c=((c<<1)&0xFFFFFFFF)
        if fb: c^=0x04C11DB7
    return (c^xorout)&0xFFFFFFFF

import itertools
inits=[0xFFFFFFFF,0x00000000]
xorouts=[0xFFFFFFFF,0x00000000]
# bit orders to try: for each V, generate bit lists
def gen_bits(V, name):
    le=V.to_bytes(4,'little'); be=V.to_bytes(4,'big')
    return {
      "int_lsb": bits_int_lsb(V),
      "int_msb": bits_int_msb(V),
      "le_lsb": bits_le_of_bytes(le),
      "le_msb": bits_be_of_bytes(le),
      "be_lsb": bits_le_of_bytes(be),
      "be_msb": bits_be_of_bytes(be),
    }[name]

found=[]
for oname in ["int_lsb","int_msb","le_lsb","le_msb","be_lsb","be_msb"]:
    for poly in ["ref","noref"]:
        for init in inits:
            for xorout in xorouts:
