                    bits=gen_bits(V,oname)
                    r=crc_ref(bits,init,xorout) if poly=="ref" else crc_noref(bits,init,xorout)
                    if r!=e:
                        ok=False; break
                if ok:
                    found.append((oname,poly,hex(init),hex(xorout)))
                    print("FULL MATCH",oname,poly,hex(init),hex(xorout))
print("done full, found:",found)
